                       earliest: str = "", latest_end: str = "") -> dict:
    def canonical_day(value):
        return str(value).strip().lower()[:3]

    def parse_time(value):
        if isinstance(value, int):
            if value < 0:
                raise ValueError
            if value <= 24:
                return value * 60
            if value < 100:
                return value
            if value == 2400:
                return 24 * 60
            if value < 2400:
                return (value // 100) * 60 + (value % 100)
            return value

        text = str(value).strip()
        if text == "":
            raise ValueError

        low = text.lower()
        am = "am" in low
        pm = "pm" in low

        core = ""
        for ch in low:
            if ch.isdigit() or ch == ":":
                core += ch

        if core == "":
            raise ValueError

        if ":" in core:
            parts = core.split(":")
            if len(parts) < 2 or parts[0] == "" or parts[1] == "":
                raise ValueError
            hour = int(parts[0])
            minute_text = ""
            for ch in parts[1]:
                if ch.isdigit():
                    minute_text += ch
                else:
                    break
            if minute_text == "":
                raise ValueError
            minute = int(minute_text[:2])
        else:
            if len(core) <= 2:
                hour = int(core)
                minute = 0
            elif len(core) == 3:
                hour = int(core[0])
                minute = int(core[1:])
            else:
                hour = int(core[:2])
                minute = int(core[2:4])

        if am or pm:
            if pm and hour < 12:
                hour += 12
            if am and hour == 12:
                hour = 0

        return hour * 60 + minute

    def parse_range(text):
        if text is None:
            raise ValueError
        value = str(text).strip()
        parts = value.split("-")
        if len(parts) != 2:
            raise ValueError
        return parse_time(parts[0]), parse_time(parts[1])

    def parse_text_times(text):
        times = []
        s = str(text)
        low = s.lower()
        n = len(s)
        i = 0
        while i < n:
            if s[i].isdigit():
                left = i
                while left > 0 and s[left - 1].isdigit():
                    left -= 1
                right = i
                saw_colon = False
                while right < n:
                    ch = s[right]
                    if ch.isdigit():
                        right += 1
                        continue
                    if ch == ":" and not saw_colon:
                        saw_colon = True
                        right += 1
                        continue
                    break
                end = right
                while end < n and s[end] == " ":
                    end += 1
                if end + 1 < n:
                    tail = low[end:end + 2]
                    if tail == "am" or tail == "pm":
                        end += 2
                token = s[left:end]
                try:
                    times.append(parse_time(token))
                except Exception:
                    pass
                i = end
            else:
                i += 1
        return times

    def event_bounds(event):
        if isinstance(event, dict):
            show_as = event.get("show_as")
            if show_as is None:
                show_as = event.get("status")
            if show_as is not None and str(show_as).strip().lower() == "free":
                return None

            start = None
            end = None
            for key in ("start", "start_time", "startTime", "begin", "from"):
                if key in event:
                    start = event[key]
                    break
            for key in ("end", "end_time", "endTime", "finish", "to"):
                if key in event:
                    end = event[key]
                    break

            if start is not None and end is not None:
                try:
                    return parse_time(start), parse_time(end)
                except Exception:
                    pass

            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        elif isinstance(event, list) or isinstance(event, tuple):
            if len(event) >= 2:
                try:
                    return parse_time(event[0]), parse_time(event[1])
                except Exception:
                    pass
            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        elif isinstance(event, str):
            low = event.lower()
            if "free" in low and "busy" not in low:
                return None
            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        return None

    def format_time(total_minutes):
        hour = total_minutes // 60
        minute = total_minutes % 60
        if hour < 10:
            hour_text = "0" + str(hour)
        else:
            hour_text = str(hour)
        if minute < 10:
            minute_text = "0" + str(minute)
        else:
            minute_text = str(minute)
        return hour_text + ":" + minute_text

    def day_match(entry_day, wanted_day):
        text = str(entry_day).strip().lower()
        return text == wanted_day or text[:3] == wanted_day

    def get_day_entry(calendar, wanted_day):
        if isinstance(calendar, dict) and "days" in calendar:
            day_list = calendar.get("days")
            if isinstance(day_list, list):
                for entry in day_list:
                    if isinstance(entry, dict) and day_match(entry.get("day", ""), wanted_day):
                        return entry
            if "events" in calendar:
                return calendar
            return None
        return calendar

    def parse_working_hours(value):
        if value is None:
            return None
        if isinstance(value, list) or isinstance(value, tuple):
            if len(value) >= 2:
                try:
                    return parse_time(value[0]), parse_time(value[1])
                except Exception:
                    return None
            return None

        text = str(value).strip()
        if text == "":
            return None

        if "-" in text:
            parts = text.split("-")
            if len(parts) >= 2:
                try:
                    return parse_time(parts[0]), parse_time(parts[1])
                except Exception:
                    pass

        times = parse_text_times(text)
        if len(times) >= 2:
            return times[0], times[1]
        return None

    def get_working_window(calendar, day_entry):
        work = None
        if isinstance(day_entry, dict) and "working_hours" in day_entry:
            work = day_entry.get("working_hours")
        if work is None and isinstance(calendar, dict) and "working_hours" in calendar:
            work = calendar.get("working_hours")
        parsed = parse_working_hours(work)
        if parsed is None:
            return 0, 24 * 60
        return parsed[0], parsed[1]

    def get_note_buffer(calendar, day_entry):
        note_text = ""
        if isinstance(day_entry, dict):
            for key in ("note", "notes", "buffer_note"):
                if key in day_entry:
                    note_text = str(day_entry.get(key))
                    break
        if note_text == "" and isinstance(calendar, dict):
            for key in ("note", "notes", "buffer_note"):
                if key in calendar:
                    note_text = str(calendar.get(key))
                    break
        low = note_text.lower()
        if low == "":
            return 0
        if "minute" not in low and "min" not in low:
            return 0
        if "leave" not in low and "between" not in low and "buffer" not in low and "gap" not in low:
            return 0

        digits = ""
        seen = False
        for ch in low:
            if ch.isdigit():
                digits += ch
                seen = True
            elif seen:
                break

        if digits == "":
            return 15
        value = int(digits)
        if value < 0:
            return 0
        if value > 240:
            return 240
        return value

    def get_items(calendar, day_entry):
        items = None
        if isinstance(day_entry, dict) and "events" in day_entry:
            items = day_entry.get("events")
        elif isinstance(day_entry, list) or isinstance(day_entry, tuple):
            items = day_entry
        elif isinstance(day_entry, str):
            items = [day_entry]
        elif isinstance(calendar, dict) and "events" in calendar:
            items = calendar.get("events")
        elif isinstance(calendar, list) or isinstance(calendar, tuple):
            items = calendar
        elif isinstance(calendar, str):
            items = [calendar]

        if items is None:
            return []
        if isinstance(items, dict):
            return [items]
        return items

    people = [""]
    for name in attendees:
        people.append(name)

    if earliest != "":
        start_limit = parse_time(earliest)
        if start_limit < 0:
            start_limit = 0
        if start_limit > 24 * 60:
            start_limit = 24 * 60
        start_limit = ((start_limit + 14) // 15) * 15
    else:
        start_limit = 0

    if latest_end != "":
        end_limit = parse_time(latest_end)
        if end_limit < 0:
            end_limit = 0
        if end_limit > 24 * 60:
            end_limit = 24 * 60
    else:
        end_limit = 24 * 60

    start_results = {}

    for day in days:
        wanted_day = canonical_day(day)
        busy = []
        window_start = 0
        window_end = 24 * 60
        first_person = True

        for person in people:
            calendar = api.read_calendar(person, day)
            day_entry = get_day_entry(calendar, wanted_day)

            if day_entry is None and canonical_day(day) != day:
                try:
                    alt_calendar = api.read_calendar(person, wanted_day)
                    alt_day_entry = get_day_entry(alt_calendar, wanted_day)
                    if alt_day_entry is not None:
                        calendar = alt_calendar
                        day_entry = alt_day_entry
                except Exception:
                    pass

            if day_entry is None:
                continue

            person_start, person_end = get_working_window(calendar, day_entry)
            if first_person:
                window_start = person_start
                window_end = person_end
                first_person = False
            else:
                if person_start > window_start:
                    window_start = person_start
                if person_end < window_end:
                    window_end = person_end

            buffer_minutes = get_note_buffer(calendar, day_entry)
            items = get_items(calendar, day_entry)
            for event in items:
                bounds = event_bounds(event)
                if bounds is None:
                    continue
                s = bounds[0]
                e = bounds[1]
                if e <= s:
                    continue
                if e <= 0 or s >= 24 * 60:
                    continue
                if buffer_minutes > 0:
                    s -= buffer_minutes
                    e += buffer_minutes
                if s < 0:
                    s = 0
                if e > 24 * 60:
                    e = 24 * 60
                if e > s:
                    busy.append((s, e))

        if window_start < start_limit:
            window_start = start_limit
        window_start = ((window_start + 14) // 15) * 15

        final_end = window_end
        if end_limit < final_end:
            final_end = end_limit

        upper = final_end - minutes
        if upper < window_start:
            continue
        upper = (upper // 15) * 15
        if upper < window_start:
            continue

        if len(busy) > 0:
            busy = sorted(busy)
            merged = [list(busy[0])]
            for s, e in busy[1:]:
                if s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
        else:
            merged = []

        slots = []
        current = window_start
        while current <= upper:
            meeting_end = current + minutes
            free = True
            for s, e in merged:
                if s >= meeting_end:
                    break
                if e > current and s < meeting_end:
                    free = False
                    break
            if free:
                slots.append(format_time(current))
            current += 15

        if len(slots) > 0:
            start_results[wanted_day] = slots

    return {"starts": start_results}
