            for key in ("start", "start_time", "startTime", "begin", "from"):
                if key in event:
                    start = event[key]
                    break
            for key in ("end", "end_time", "endTime", "finish", "to"):
                if key in event:
                    end = event[key]
                    break

            if start is not None and end is not None:
                try:
                    return parse_time(start), parse_time(end)
                except Exception:
                    pass

            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        elif isinstance(event, list) or isinstance(event, tuple):
            if len(event) >= 2:
                try:
                    return parse_time(event[0]), parse_time(event[1])
                except Exception:
                    pass
            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        elif isinstance(event, str):
            low = event.lower()
            if "free" in low and "busy" not in low:
                return None
            times = parse_text_times(event)
            if len(times) >= 2:
                return times[0], times[1]

        return None

    def format_time(total_minutes):
        hour = total_minutes // 60
        minute = total_minutes % 60
        if hour < 10:
            hour_text = "0" + str(hour)
        else:
            hour_text = str(hour)
        if minute < 10:
            minute_text = "0" + str(minute)
        else:
            minute_text = str(minute)
        return hour_text + ":" + minute_text

    def find_day_entry(calendar, wanted_day):
        if isinstance(calendar, dict) and "days" in calendar:
            day_list = calendar.get("days")
            if isinstance(day_list, list):
                for entry in day_list:
                    if isinstance(entry, dict) and canonical_day(entry.get("day", "")) == wanted_day:
                        return entry
            return None
        return calendar

    def get_working_window(calendar, day_entry):
        work = None
        if isinstance(day_entry, dict) and "working_hours" in day_entry:
            work = day_entry.get("working_hours")
        if work is None and isinstance(calendar, dict) and "working_hours" in calendar:
            work = calendar.get("working_hours")
        if work is None:
            return 0, 24 * 60
        if isinstance(work, list) or isinstance(work, tuple):
            if len(work) >= 2:
                try:
                    return parse_time(work[0]), parse_time(work[1])
                except Exception:
                    return 0, 24 * 60
            return 0, 24 * 60
        try:
            return parse_range(work)
        except Exception:
            return 0, 24 * 60

