        note_text = ""
        if isinstance(day_entry, dict):
            for key in ("note", "notes", "buffer_note"):
                if key in day_entry:
                    note_text = str(day_entry.get(key))
                    break
        if note_text == "" and isinstance(calendar, dict):
            for key in ("note", "notes", "buffer_note"):
                if key in calendar:
                    note_text = str(calendar.get(key))
                    break

        low = note_text.lower()
        if low == "":
            return 0
        if "minute" not in low and "min" not in low:
            return 0
        if "leave" not in low and "between" not in low and "buffer" not in low and "gap" not in low:
            return 0

        digits = ""
        seen = False
        for ch in low:
            if ch.isdigit():
                digits += ch
                seen = True
            elif seen:
                break

        if digits == "":
            return 15
        value = int(digits)
        if value < 0:
            return 0
        if value > 240:
            return 240
        return value

    def get_items(calendar, day_entry):
        items = None
        if isinstance(day_entry, dict) and "events" in day_entry:
            items = day_entry.get("events")
        elif isinstance(day_entry, list) or isinstance(day_entry, tuple):
            items = day_entry
        elif isinstance(day_entry, str):
            items = [day_entry]
        elif isinstance(calendar, dict) and "events" in calendar:
            items = calendar.get("events")
        elif isinstance(calendar, list) or isinstance(calendar, tuple):
            items = calendar
        elif isinstance(calendar, str):
            items = [calendar]

        if items is None:
            return []
        if isinstance(items, dict):
            return [items]
        return items

    people = [""]
    for name in attendees:
        people.append(name)

    if earliest != "":
        start_limit = parse_time(earliest)
        if start_limit < 0:
            start_limit = 0
        if start_limit > 24 * 60:
            start_limit = 24 * 60
        start_limit = ((start_limit + 14) // 15) * 15
    else:
        start_limit = 0

    if latest_end != "":
        end_limit = parse_time(latest_end)
        if end_limit < 0:
            end_limit = 0
        if end_limit > 24 * 60:
            end_limit = 24 * 60
    else:
        end_limit = 24 * 60

    start_results = {}

    for day in days:
        wanted_day = canonical_day(day)
        busy = []
        window_start = 0
        window_end = 24 * 60
        first_person = True

        for person in people:
            calendar = api.read_calendar(person, day)
            day_entry = find_day_entry(calendar, wanted_day)

            if day_entry is None and wanted_day != canonical_day(day):
                try:
                    alt_calendar = api.read_calendar(person, wanted_day)
                    alt_day_entry = find_day_entry(alt_calendar, wanted_day)
                    if alt_day_entry is not None:
                        calendar = alt_calendar
                        day_entry = alt_day_entry
                except Exception:
                    pass

            if day_entry is None:
                day_entry = {}

            person_start, person_end = get_working_window(calendar, day_entry)
            if first_person:
                window_start = person_start
                window_end = person_end
                first_person = False
            else:
                if person_start > window_start:
                    window_start = person_start
                if person_end < window_end:
                    window_end = person_end

            buffer_minutes = get_note_buffer(calendar, day_entry)
            items = get_items(calendar, day_entry)
            for event in items:
                bounds = event_bounds(event)
                if bounds is None:
                    continue
                s = bounds[0]
                e = bounds[1]
                if e <= s:
                    continue
                if e <= 0 or s >= 24 * 60:
                    continue
                if buffer_minutes > 0:
                    s -= buffer_minutes
                    e += buffer_minutes
                if s < 0:
                    s = 0
                if e > 24 * 60:
                    e = 24 * 60
                if e > s:
                    busy.append((s, e))

        if window_start < start_limit:
            window_start = start_limit
        window_start = ((window_start + 14) // 15) * 15

        final_end = window_end
        if end_limit < final_end:
            final_end = end_limit

        upper = final_end - minutes
        if upper < window_start:
            continue
        upper = (upper // 15) * 15
        if upper < window_start:
            continue

        if len(busy) > 0:
            busy = sorted(busy)
            merged = [list(busy[0])]
            for s, e in busy[1:]:
                if s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
        else:
            merged = []

        slots = []
        current = window_start
        while current <= upper:
            meeting_end = current + minutes
            free = True
            for s, e in merged:
                if s >= meeting_end:
                    break
                if e > current and s < meeting_end:
                    free = False
                    break
            if free:
                slots.append(format_time(current))
            current += 15

        if len(slots) > 0:
            start_results[day] = slots

    return {"starts": start_results}
