def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def canonical_day(value):
        return str(value).strip().lower()[:3]

    def day_match(entry_day, wanted_day):
        text = str(entry_day).strip().lower()
        return text == wanted_day or text[:3] == wanted_day

    def parse_time(value):
        if isinstance(value, int):
            if value < 0:
                raise ValueError
            if value <= 24:
                return value * 60
            if value < 100:
                return value
            if value == 2400:
                return 24 * 60
            if value < 2400:
                return (value // 100) * 60 + (value % 100)
            return value

        text = str(value).strip()
        if text == "":
            raise ValueError

        low = text.lower()

        # Prefer a trailing time-like token if the input looks like a datetime.
        candidate = text
        split_text = text.replace("T", " ").replace("t", " ")
        parts = split_text.split()
        if len(parts) >= 2:
            last = parts[-1].strip()
            prev = parts[-2].strip()
            if last in ("am", "pm") and prev != "":
                candidate = prev + " " + last
            elif ":" in last or last.endswith("am") or last.endswith("pm"):
                candidate = last

        candidate_low = candidate.lower().strip()
        if candidate_low.endswith("am") or candidate_low.endswith("pm"):
            suffix = candidate_low[-2:]
            candidate = candidate[:-2].strip()
            candidate_low = candidate_low[:-2].strip()
            am = suffix == "am"
            pm = suffix == "pm"
        else:
            am = "am" in candidate_low
            pm = "pm" in candidate_low

        # Trim timezone or trailing range-like suffix after a valid time token.
        cut = len(candidate)
        seen_colon = False
        for idx, ch in enumerate(candidate):
            if ch == ":":
                seen_colon = True
            elif seen_colon and (ch == "+" or ch == "-"):
                cut = idx
                break
        candidate = candidate[:cut].strip()

        core = ""
        for ch in candidate:
            if ch.isdigit() or ch == ":":
                core += ch

        if core == "":
            raise ValueError

        if ":" in core:
            parts = core.split(":")
            if len(parts) < 2 or parts[0] == "" or parts[1] == "":
                raise ValueError
            hour = int(parts[0])
            minute_text = ""
            for ch in parts[1]:
                if ch.isdigit():
                    minute_text += ch
                else:
                    break
            if minute_text == "":
                raise ValueError
            minute = int(minute_text[:2])
        else:
            if len(core) <= 2:
                hour = int(core)
                minute = 0
            elif len(core) == 3:
                hour = int(core[0])
                minute = int(core[1:])
            else:
                hour = int(core[:2])
                minute = int(core[2:4])

        if am or pm:
            if pm and hour < 12:
                hour += 12
            if am and hour == 12:
                hour = 0

        return hour * 60 + minute

    def parse_range(text):
        if text is None:
            raise ValueError
        value = str(text).strip()
        parts = value.split("-")
        if len(parts) != 2:
            raise ValueError
        return parse_time(parts[0]), parse_time(parts[1])

    def parse_text_times(text):
